const root=document.querySelector('#prazos-view'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),dt=v=>v?v.split('-').reverse().join('/'):'—',today=()=>new Date().toISOString().slice(0,10);
let orders=[],editingId=null;
const dateKey=v=>{const x=String(v||'').trim();if(/^\d{4}-\d{2}-\d{2}$/.test(x))return x;const m=x.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);return m?m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0'):''};const effective=r=>dateKey(r.newDate)||dateKey(r.deliveryDate),statuses=['Aguardando entrega','Entregue','Cancelado'];
const num=v=>{const n=Number(String(v??'').replace(/\./g,'').replace(',','.'));return Number.isFinite(n)?n:0},fmt=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:3}).format(n);
const delivered=r=>num(r.deliveredQuantity),remaining=r=>Math.max(0,num(r.quantity)-delivered(r)),isPartial=r=>r.status==='Aguardando entrega'&&delivered(r)>0;
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
const similarity=(a,b)=>{const A=new Set(norm(a).split(' ').filter(x=>x.length>2)),B=new Set(norm(b).split(' ').filter(x=>x.length>2));if(!A.size||!B.size)return 0;const common=[...A].filter(x=>B.has(x)).length;return common/Math.max(A.size,B.size)};
async function enrichImportedOrder(j){let catalog=[];try{const r=await fetch('/data.json');if(r.ok)catalog=(await r.json()).catalog||[]}catch{}
 const history=[...orders];
 for(const item of j.items||[]){let candidates=[...history.map(x=>({code:x.code,product:x.product})),...catalog.map(x=>({code:x.id,product:x.name}))];let best=null;for(const c of candidates){const score=similarity(item.product,c.product);if(!best||score>best.score)best={...c,score}}if(best&&best.score>=.55){item.code=best.code;item.codeMatched=true;}}
 if(j.supplier){const same=history.filter(x=>norm(x.supplier)===norm(j.supplier)&&x.contact).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));if(same[0]){j.contact=same[0].contact;j.contactMatched=true;}}
 return j}
root.innerHTML=`<div class="deadline-kpis"></div><section class="panel deadline-purchase-entry"><details><summary>+ Adicionar pedido comprado</summary><div class="deadline-pdf-import"><strong>Importar pedido do FoccoERP</strong><input type="file" data-purchase-pdf accept="application/pdf,.pdf"><button type="button" data-import-purchase-pdf>Importar PDF</button><span data-purchase-pdf-status></span></div><form data-purchase-form><div class="deadline-purchase-common"><label>Pedido de compra<input name="purchaseOrder" required></label><label>Contato / comprador<input name="contact"></label><label>Fornecedor<input name="supplier" required></label><label>Entrega prevista<input name="deliveryDate" type="date" required></label><label>Frete<input name="freight" placeholder="CIF, FOB..."></label><label>Observação<input name="notes"></label></div><div class="deadline-purchase-items"><strong>Itens do pedido</strong><div data-purchase-items></div><button type="button" data-add-purchase-item>+ Adicionar item</button><small>Um mesmo pedido pode ter vários itens. Cada item será acompanhado separadamente para entrega parcial, saldo e reprogramação.</small></div><button type="submit" data-purchase-save>Salvar pedido comprado</button><button type="button" data-cancel-purchase-edit hidden>Cancelar edição</button><p class="deadline-entry-message" role="status"></p></form></details></section><section class="panel"><h3>Controle dos prazos</h3><p class="hint">Branco: prazo normal · Azul: entrega na próxima semana · Vermelho: atrasado · Verde: entregue. Entrega parcial continua pendente até o saldo ser recebido.</p><div class="cement-filters"><label>Fornecedor<input data-supplier type="search" placeholder="Todos"></label><label>Status<select data-status><option value="">Todos</option><option value="Parcial">Parcial</option>${statuses.map(x=>'<option>'+x+'</option>').join('')}</select></label><label>Buscar<input data-search type="search" placeholder="Código, produto ou pedido"></label></div><div class="deadline-table"></div><p class="cement-message"></p></section>`;
const msg=root.querySelector('.cement-message'),entryMsg=root.querySelector('.deadline-entry-message'),purchaseItems=root.querySelector('[data-purchase-items]');
function addPurchaseItem(values={}){const row=document.createElement('div');row.className='deadline-purchase-item';row.innerHTML='<label>Código<input name="code" required value="'+esc(values.code||'')+'"></label><label class="deadline-purchase-product">Produto<input name="product" required value="'+esc(values.product||'')+'"></label><label>Quantidade<input name="quantity" inputmode="decimal" required value="'+esc(values.quantity||'')+'"></label><label>Entrega do item<input name="itemDeliveryDate" type="date" value="'+esc(values.deliveryDate||values.itemDeliveryDate||'')+'"></label><label>UN<input name="unit" required value="'+esc(values.unit||'')+'"></label><button type="button" class="deadline-icon-btn" data-remove-purchase title="Remover item" aria-label="Remover item">×</button>';row.querySelector('[data-remove-purchase]').onclick=()=>{if(purchaseItems.children.length>1)row.remove()};purchaseItems.append(row)}
addPurchaseItem();root.querySelector('[data-add-purchase-item]').onclick=()=>addPurchaseItem();
root.querySelector('[data-import-purchase-pdf]').onclick=async()=>{const file=root.querySelector('[data-purchase-pdf]').files[0],status=root.querySelector('[data-purchase-pdf-status]');if(!file){status.textContent='Selecione o PDF do pedido.';return}status.textContent='Lendo pedido…';try{const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]||'');reader.onerror=()=>reject(Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file)});const res=await fetch('/api/deadlines/import-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file:{name:file.name,content}})}),j=await res.json();if(!res.ok)throw Error(j.error);await enrichImportedOrder(j);const form=root.querySelector('[data-purchase-form]');form.elements.purchaseOrder.value=j.purchaseOrder||'';form.elements.contact.value=j.contact||'';form.elements.supplier.value=j.supplier||'';form.elements.deliveryDate.value=j.deliveryDate||'';form.elements.freight.value=j.freight||'';form.elements.notes.value=[j.paymentTerms?'Pgto: '+j.paymentTerms:'',j.warning||''].filter(Boolean).join(' · ');purchaseItems.innerHTML='';(j.items||[]).forEach(addPurchaseItem);status.textContent='Pedido '+j.purchaseOrder+' lido: '+(j.items||[]).length+' item(ns). '+((j.items||[]).filter(x=>x.codeMatched).length?'Códigos conferidos pelo histórico/cadastro. ':'')+(j.contactMatched?'Contato recuperado do histórico do fornecedor. ':'')+'Confira e clique em Salvar pedido comprado.';form.scrollIntoView({behavior:'smooth',block:'start'})}catch(err){status.textContent=err.message}};root.querySelector('[data-purchase-form]').onsubmit=savePurchasedOrder;root.querySelector('[data-cancel-purchase-edit]').onclick=()=>resetPurchaseForm();
function resetPurchaseForm(){const form=root.querySelector('[data-purchase-form]');editingId=null;form.reset();purchaseItems.innerHTML='';addPurchaseItem();root.querySelector('[data-add-purchase-item]').hidden=false;root.querySelector('[data-purchase-save]').textContent='Salvar pedido comprado';root.querySelector('[data-cancel-purchase-edit]').hidden=true;root.querySelector('.deadline-purchase-entry summary').textContent='+ Adicionar pedido comprado'}
function editPurchasedOrder(id){const r=orders.find(x=>x.id===id);if(!r)return;editingId=id;const details=root.querySelector('.deadline-purchase-entry details'),form=root.querySelector('[data-purchase-form]');details.open=true;for(const k of ['purchaseOrder','contact','supplier','deliveryDate','freight','notes'])form.elements[k].value=r[k]||'';purchaseItems.innerHTML='';addPurchaseItem(r);root.querySelector('[data-add-purchase-item]').hidden=true;root.querySelector('[data-purchase-save]').textContent='Salvar alterações';root.querySelector('[data-cancel-purchase-edit]').hidden=false;root.querySelector('.deadline-purchase-entry summary').textContent='Editando: '+r.code+' · '+r.product;entryMsg.textContent='Edite os campos necessários e clique em Salvar alterações.';details.scrollIntoView({behavior:'smooth',block:'start'})}
root.querySelectorAll('[data-supplier],[data-status],[data-search]').forEach(x=>x.oninput=render);
function localDate(s){return new Date(s+'T12:00:00')}
function nextWeekRange(){const d=localDate(today()),day=(d.getDay()+6)%7,monday=new Date(d);monday.setDate(d.getDate()-day+7);const friday=new Date(monday);friday.setDate(monday.getDate()+4);return [monday.toISOString().slice(0,10),friday.toISOString().slice(0,10)]}
function cls(r){if(r.status==='Entregue')return'deadline-delivered';if(r.status==='Cancelado')return'';const d=effective(r),t=today();if(d<t)return'deadline-late';const [start,end]=nextWeekRange();return d>=start&&d<=end?'deadline-nextweek':''}
function shownStatus(r){return isPartial(r)?'Parcial':r.status}
function payload(r,patch={}){const input={...r,...patch};return Object.fromEntries(['id','version','code','product','purchaseOrder','contact','supplier','status','deliveryDate','quantity','freight','unit','newDate','notes','deliveredQuantity','deliveryEventsJson'].map(k=>[k,input[k]??'']))}
async function savePurchasedOrder(e){e.preventDefault();const form=e.currentTarget,fd=new FormData(form),common={purchaseOrder:String(fd.get('purchaseOrder')||'').trim(),contact:String(fd.get('contact')||'').trim(),supplier:String(fd.get('supplier')||'').trim(),deliveryDate:String(fd.get('deliveryDate')||''),freight:String(fd.get('freight')||'').trim(),notes:String(fd.get('notes')||'').trim()};const items=[...purchaseItems.querySelectorAll('.deadline-purchase-item')].map(row=>({code:row.querySelector('[name="code"]').value.trim(),product:row.querySelector('[name="product"]').value.trim(),quantity:row.querySelector('[name="quantity"]').value.trim(),unit:row.querySelector('[name="unit"]').value.trim(),deliveryDate:row.querySelector('[name="itemDeliveryDate"]').value||common.deliveryDate}));if(!common.purchaseOrder||!common.supplier||!common.deliveryDate||items.some(i=>!i.code||!i.product||!i.quantity||!i.unit)){entryMsg.textContent='Preencha os campos obrigatórios do pedido e de todos os itens.';return}try{form.querySelector('button[type="submit"]').disabled=true;if(editingId){const original=orders.find(x=>x.id===editingId);if(!original)throw Error('Item não encontrado para edição.');const item=items[0],res=await fetch('/api/deadlines',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload(original,{...common,...item}))}),j=await res.json();if(!res.ok)throw Error(j.error);entryMsg.textContent='Alterações salvas no item '+item.code+'.';resetPurchaseForm()}else{for(const item of items){const res=await fetch('/api/deadlines',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...common,...item,deliveryDate:item.deliveryDate||common.deliveryDate,status:'Aguardando entrega',newDate:'',deliveredQuantity:'',deliveryEventsJson:''})}),j=await res.json();if(!res.ok)throw Error(j.error)}entryMsg.textContent='Pedido '+common.purchaseOrder+' salvo com '+items.length+' item(ns) e incluído no controle de prazos.';resetPurchaseForm()}await refresh(true)}catch(err){entryMsg.textContent=err.message}finally{form.querySelector('button[type="submit"]').disabled=false}}
async function save(r,patch,message){try{busy(true);const res=await fetch('/api/deadlines',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload(r,patch))}),j=await res.json();if(!res.ok)throw Error(j.error);msg.textContent=message;await refresh(true)}catch(e){msg.textContent=e.message}finally{busy(false)}}
function render(){const t=today(),[nwStart,nwEnd]=nextWeekRange(),pending=orders.filter(r=>r.status==='Aguardando entrega'),late=pending.filter(r=>effective(r)<t).length,next=pending.filter(r=>effective(r)>=nwStart&&effective(r)<=nwEnd).length,partial=pending.filter(isPartial).length,done=orders.filter(r=>r.status==='Entregue').length;
root.querySelector('.deadline-kpis').innerHTML=`<div><strong>${late}</strong><span>Atrasados</span></div><div><strong>${next}</strong><span>Próxima semana</span></div><div><strong>${pending.length}</strong><span>Pendentes</span></div><div><strong>${partial}</strong><span>Parciais</span></div><div><strong>${done}</strong><span>Entregues</span></div>`;
const q=root.querySelector('[data-search]').value.toLowerCase(),sup=root.querySelector('[data-supplier]').value.toLowerCase(),st=root.querySelector('[data-status]').value,rows=orders.filter(r=>(!sup||r.supplier.toLowerCase().includes(sup))&&(!st||(st==='Parcial'?isPartial(r):r.status===st))&&(!q||(r.code+' '+r.product+' '+r.purchaseOrder).toLowerCase().includes(q))).sort((a,b)=>{const group=r=>r.status==='Entregue'?3:(cls(r)==='deadline-late'?0:(cls(r)==='deadline-nextweek'?1:2));const ag=group(a),bg=group(b);if(ag!==bg)return ag-bg;const ae=dateKey(a.deliveryDate),be=dateKey(b.deliveryDate);if(!ae&&be)return 1;if(ae&&!be)return -1;if(ae!==be)return ae.localeCompare(be);return String(a.purchaseOrder||'').localeCompare(String(b.purchaseOrder||''),undefined,{numeric:true})});
root.querySelector('.deadline-table').innerHTML=rows.length?'<div class="table-scroll"><table class="deadlines-grid"><thead><tr><th>Cód</th><th>Produto</th><th>Pedido</th><th>Contato</th><th>Fornecedor</th><th>Status</th><th class="deadline-date-col">Entrega prevista</th><th>Pedido</th><th>Entregue</th><th>Saldo</th><th>UN</th><th class="deadline-newdate-col">Nova data</th><th>Ações</th></tr></thead><tbody>'+rows.map(r=>'<tr class="'+cls(r)+'" data-edit-row="'+r.id+'" title="Clique para editar este item"><td class="deadline-code">'+esc(r.code)+'</td><td class="deadline-product" title="'+esc(r.product)+'">'+esc(r.product)+'</td><td>'+esc(r.purchaseOrder)+'</td><td>'+esc(r.contact||'—')+'</td><td>'+esc(r.supplier)+'</td><td>'+esc(shownStatus(r))+'</td><td class="deadline-date-col">'+dt(r.deliveryDate)+'</td><td>'+esc(r.quantity)+'</td><td>'+fmt(delivered(r))+'</td><td>'+fmt(remaining(r))+'</td><td>'+esc(r.unit)+'</td><td class="deadline-newdate-col"><div class="deadline-date-edit"><input type="date" data-date="'+r.id+'" value="'+esc(r.newDate||'')+'" '+(r.status==='Entregue'?'disabled':'')+'><button class="deadline-icon-btn" data-save-date="'+r.id+'" title="Salvar nova data" aria-label="Salvar nova data" '+(r.status==='Entregue'?'disabled':'')+'>✎</button></div></td><td><div class="deadline-actions">'+(r.status==='Aguardando entrega'?'<button class="deadline-icon-btn" data-partial="'+r.id+'" title="Registrar entrega parcial" aria-label="Registrar entrega parcial">½</button><button class="deadline-icon-btn deadline-ok-btn" data-confirm="'+r.id+'" title="Confirmar entrega do saldo" aria-label="Confirmar entrega do saldo">✓</button>':'—')+'</div></td></tr>').join('')+'</tbody></table></div><div class="deadline-scroll-dock" aria-label="Rolagem horizontal da tabela"><div></div></div>':'<p class="empty-state">Nenhum pedido cadastrado.</p>';
const mainScroll=root.querySelector('.deadline-table .table-scroll'),dock=root.querySelector('.deadline-scroll-dock');
if(mainScroll&&dock){const inner=dock.firstElementChild,syncWidth=()=>inner.style.width=mainScroll.scrollWidth+'px';syncWidth();dock.onscroll=()=>{if(mainScroll.scrollLeft!==dock.scrollLeft)mainScroll.scrollLeft=dock.scrollLeft};mainScroll.onscroll=()=>{if(dock.scrollLeft!==mainScroll.scrollLeft)dock.scrollLeft=mainScroll.scrollLeft};requestAnimationFrame(syncWidth)}

root.querySelectorAll('[data-partial]').forEach(b=>b.onclick=()=>partialDelivery(b.dataset.partial));
root.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>confirmDelivery(b.dataset.confirm));
root.querySelectorAll('[data-save-date]').forEach(b=>b.onclick=()=>changeDate(b.dataset.saveDate));root.querySelectorAll('[data-edit-row]').forEach(tr=>tr.onclick=e=>{if(e.target.closest('button,input,select,a'))return;editPurchasedOrder(tr.dataset.editRow)})}
async function partialDelivery(id){const r=orders.find(x=>x.id===id);if(!r)return;const raw=prompt('Quantidade recebida agora ('+r.unit+'). Saldo atual: '+fmt(remaining(r))+' '+r.unit);if(raw==null)return;const amount=num(raw);if(amount<=0||amount>=remaining(r)){msg.textContent='Na entrega parcial, informe uma quantidade maior que zero e menor que o saldo. Para finalizar, use “Entregar saldo”.';return}const total=delivered(r)+amount,events=JSON.parse(r.deliveryEventsJson||'[]');events.push({at:new Date().toISOString(),quantity:String(amount),type:'Parcial'});await save(r,{status:'Aguardando entrega',deliveredQuantity:String(total),deliveryEventsJson:JSON.stringify(events)},'Entrega parcial registrada. O pedido continua pendente.')}
async function confirmDelivery(id){const r=orders.find(x=>x.id===id);if(!r)return;if(!confirm('Confirmar recebimento do saldo de '+fmt(remaining(r))+' '+r.unit+'?'))return;const events=JSON.parse(r.deliveryEventsJson||'[]');events.push({at:new Date().toISOString(),quantity:String(remaining(r)),type:'Final'});await save(r,{status:'Entregue',deliveredQuantity:String(num(r.quantity)),deliveryEventsJson:JSON.stringify(events)},'Entrega final confirmada.')}
async function changeDate(id){const r=orders.find(x=>x.id===id);if(!r)return;const value=root.querySelector('[data-date="'+CSS.escape(id)+'"]').value;if(value===r.newDate)return;await save(r,{newDate:value},value?'Nova data de entrega salva. A data original foi preservada.':'Nova data removida; voltou a valer a data original.')}
function busy(on){root.querySelectorAll('.deadline-table button,.deadline-table input').forEach(b=>b.disabled=on)}
async function refresh(notify=false){const r=await fetch('/api/deadlines'),j=await r.json();if(!r.ok)throw Error(j.error);orders=j.orders||[];render();if(notify)window.dispatchEvent(new CustomEvent('planning:data-changed',{detail:{message:'Pedido alterado. MRP, cobertura e Dashboard recalculados.'}}))}
refresh().catch(e=>msg.textContent=e.message);
